PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, game_username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, scope TEXT NOT NULL CHECK(scope IN ('technical','judicial','public')));
CREATE TABLE user_roles (user_id TEXT NOT NULL REFERENCES users(id), role_id TEXT NOT NULL REFERENCES roles(id), granted_by TEXT REFERENCES users(id), granted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at TEXT, PRIMARY KEY(user_id,role_id,granted_at));
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cases (id TEXT PRIMARY KEY, case_number TEXT NOT NULL UNIQUE, case_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','triage','rejected','instruction','hearing','decided','appeal','closed')), visibility TEXT NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','restricted','sealed')), filed_by TEXT NOT NULL REFERENCES users(id), assigned_judge TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE case_parties (case_id TEXT NOT NULL REFERENCES cases(id), user_id TEXT NOT NULL REFERENCES users(id), party_type TEXT NOT NULL CHECK(party_type IN ('claimant','respondent','representative')), PRIMARY KEY(case_id,user_id,party_type));
CREATE TABLE case_events (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), actor_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE case_documents (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), uploaded_by TEXT NOT NULL REFERENCES users(id), storage_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, sha256 TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('public','parties','judges','sealed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE decisions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), author_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL, constitutional_basis TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), published_at TEXT, supersedes_id TEXT REFERENCES decisions(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((status='draft' AND published_at IS NULL) OR (status='published' AND published_at IS NOT NULL)));
CREATE TABLE votes (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), judge_id TEXT NOT NULL REFERENCES users(id), position TEXT NOT NULL, reasoning TEXT NOT NULL, published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE legal_norms (id TEXT PRIMARY KEY, norm_type TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, effective_from TEXT, effective_until TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE constitutional_reviews (id TEXT PRIMARY KEY, case_id TEXT NOT NULL UNIQUE REFERENCES cases(id), challenged_norm_id TEXT REFERENCES legal_norms(id), constitutional_arguments TEXT NOT NULL, effects TEXT);
CREATE TABLE consultations (id TEXT PRIMARY KEY, requester_id TEXT NOT NULL REFERENCES users(id), question TEXT NOT NULL, answer TEXT, answered_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, metadata TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER published_decisions_no_update BEFORE UPDATE ON decisions WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'published decision is immutable'); END;
CREATE TRIGGER published_decisions_no_delete BEFORE DELETE ON decisions WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'published decision cannot be deleted'); END;
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_logs BEGIN SELECT RAISE(ABORT,'audit logs are append-only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_logs BEGIN SELECT RAISE(ABORT,'audit logs are append-only'); END;
